package com.dating.backend.matching;
import com.dating.backend.entity.User;import com.dating.backend.admin.AdminService;import jakarta.persistence.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class CommunityService {
 private final EntityManager em;private final InboxService inbox;
 public record Write(String category,String title,String body,Long parentId){}
 public record View(Long id,Long parentId,String category,String title,String body,String author,boolean mine,boolean hidden,Instant createdAt){}
 public record Thread(View post,List<View> comments){}
 public record Flag(Long reportId,Long postId,String reason,View post){}
 private ResponseStatusException fail(int n,String text){return new ResponseStatusException(HttpStatus.valueOf(n),text);}
 private User member(String email){return inbox.user(email);}
 private boolean blocked(Long me,Long other){if(me.equals(other))return false;return em.createQuery("select count(v) from MemberVisibility v where v.blocked=true and ((v.ownerId=:a and v.targetId=:b) or (v.ownerId=:b and v.targetId=:a))",Long.class).setParameter("a",me).setParameter("b",other).getSingleResult()>0||em.createQuery("select count(r) from UserReport r where r.contactReleasedAt is null and ((r.reporterUserId=:a and r.reportedUserId=:b) or (r.reporterUserId=:b and r.reportedUserId=:a))",Long.class).setParameter("a",me).setParameter("b",other).getSingleResult()>0;}
 private CommunityPost visible(Long id,User u){var p=em.find(CommunityPost.class,id);if(p==null||p.isDeleted()||p.isHidden()||blocked(u.getId(),p.getAuthorId())||!"ACTIVE".equals(em.find(User.class,p.getAuthorId()).getStatus()))throw fail(404,"게시글을 찾을 수 없습니다.");return p;}
 private View view(CommunityPost p,User me){var author=em.find(User.class,p.getAuthorId());return new View(p.getId(),p.getParentId(),p.getCategory(),p.getTitle(),p.getBody(),author==null?"탈퇴한 회원":author.getNickname(),me!=null&&me.getId().equals(p.getAuthorId()),p.isHidden(),p.getCreatedAt());}
 @Transactional(readOnly=true) public List<View> list(String email,String category,long before){var me=member(email);var query=em.createQuery("select p from CommunityPost p, User u where u.id=p.authorId and u.status='ACTIVE' and p.parentId is null and p.deleted=false and p.hidden=false and (:before=0 or p.id<:before) and (:cat='ALL' or p.category=:cat) and not exists(select v.id from MemberVisibility v where v.blocked=true and ((v.ownerId=:me and v.targetId=p.authorId) or (v.targetId=:me and v.ownerId=p.authorId))) and not exists(select r.id from UserReport r where r.contactReleasedAt is null and ((r.reporterUserId=:me and r.reportedUserId=p.authorId) or (r.reportedUserId=:me and r.reporterUserId=p.authorId))) order by p.id desc",CommunityPost.class).setParameter("before",Math.max(0,before)).setParameter("cat",category).setParameter("me",me.getId());return query.setMaxResults(20).getResultList().stream().map(p->view(p,me)).toList();}
 @Transactional(readOnly=true) public Thread thread(String email,Long id){var me=member(email);var post=visible(id,me);if(post.getParentId()!=null)throw fail(404,"게시글을 찾을 수 없습니다.");var comments=em.createQuery("select p from CommunityPost p, User u where u.id=p.authorId and u.status='ACTIVE' and p.parentId=:id and p.hidden=false and p.deleted=false order by p.id desc",CommunityPost.class).setParameter("id",id).setMaxResults(50).getResultList().stream().filter(p->!blocked(me.getId(),p.getAuthorId())).map(p->view(p,me)).toList();var ordered=new ArrayList<>(comments);Collections.reverse(ordered);return new Thread(view(post,me),ordered);}
 @Transactional public View create(String email,Write w){var me=member(email);em.lock(me,LockModeType.PESSIMISTIC_WRITE);if(w==null||w.body()==null||w.body().isBlank()||w.body().length()>3000)throw fail(400,"내용은 1~3,000자로 입력해 주세요.");boolean reply=w.parentId()!=null;long count=em.createQuery("select count(p) from CommunityPost p where p.authorId=:me and p.createdAt>:start",Long.class).setParameter("me",me.getId()).setParameter("start",LocalDate.now(ZoneId.of("Asia/Seoul")).atStartOfDay(ZoneId.of("Asia/Seoul")).toInstant()).getSingleResult();if(count>=100)throw fail(429,"오늘 작성 한도에 도달했어요.");var recent=em.createQuery("select count(p) from CommunityPost p where p.authorId=:me and p.createdAt>:start",Long.class).setParameter("me",me.getId()).setParameter("start",Instant.now().minusSeconds(10)).getSingleResult();if(recent>0)throw fail(429,"잠시 후 다시 작성해 주세요.");var p=new CommunityPost();p.setAuthorId(me.getId());p.setBody(w.body().trim());if(reply){var parent=visible(w.parentId(),me);if(parent.getParentId()!=null)throw fail(400,"댓글에는 답글을 작성할 수 없습니다.");p.setParentId(parent.getId());p.setCategory(parent.getCategory());}else{if(!Set.of("ADVICE","DATING","DAILY").contains(w.category()==null?"":w.category())||w.title()==null||w.title().isBlank()||w.title().length()>80)throw fail(400,"게시판과 제목(1~80자)을 확인해 주세요.");p.setCategory(w.category());p.setTitle(w.title().trim());}em.persist(p);return view(p,me);}
 @Transactional public void delete(String email,Long id){var me=member(email);var p=em.find(CommunityPost.class,id,LockModeType.PESSIMISTIC_WRITE);if(p==null||!p.getAuthorId().equals(me.getId()))throw fail(404,"삭제할 글을 찾을 수 없습니다.");p.setDeleted(true);}
 @Transactional public void report(String email,Long id,String reason){var me=member(email);em.lock(me,LockModeType.PESSIMISTIC_WRITE);var p=visible(id,me);if(p.getAuthorId().equals(me.getId()))throw fail(400,"내 글은 신고할 수 없습니다.");if(reason==null||reason.isBlank()||reason.length()>500)throw fail(400,"신고 사유를 1~500자로 입력해 주세요.");if(em.createQuery("select count(r) from CommunityReport r where r.postId=:p and r.reporterId=:u",Long.class).setParameter("p",id).setParameter("u",me.getId()).getSingleResult()>0)return;var flag=new CommunityReport();flag.setPostId(id);flag.setReporterId(me.getId());flag.setReason(reason.trim());em.persist(flag);}
 private void admin(){AdminService.requireSession();var p=(AdminService.Principal)org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!Set.of("OWNER","SUPPORT").contains(p.role()))throw fail(403,"커뮤니티 관리 권한이 없습니다.");}
 @Transactional(readOnly=true) public List<Flag> reports(long before){admin();return em.createQuery("select r from CommunityReport r where (:before=0 or r.id<:before) order by r.id desc",CommunityReport.class).setParameter("before",Math.max(0,before)).setMaxResults(30).getResultList().stream().map(r->new Flag(r.getId(),r.getPostId(),r.getReason(),view(em.find(CommunityPost.class,r.getPostId()),null))).toList();}
 @Transactional public void moderate(Long id,boolean hidden){admin();var p=em.find(CommunityPost.class,id,LockModeType.PESSIMISTIC_WRITE);if(p==null)throw fail(404,"게시글을 찾을 수 없습니다.");p.setHidden(hidden);}
}
